mapper.select:
SELECT COUNT(*)
FROM TB_ORDER o
         JOIN TB_ORDER_ITEM oi ON o.ORDERNO = oi.ORDERNO
WHERE o.MEMID = #{memId}
  AND o.ORDEREDAT BETWEEN #{startDateTime} AND #{endDateTime}

mapper.update:
UPDATE TB_ORDER_ITEM
SET CONFIRM_YN = #{yn}
WHERE ORDERNO = #{orderNo}
  AND PROID = #{proId}

UPDATE TB_ORDER_ITEM
SET EXCHANGE_YN = #{yn}
WHERE ORDERNO = #{orderNo}
  AND PROID = #{proId}

UPDATE TB_ORDER_ITEM
SET RETURN_YN = #{yn}
WHERE ORDERNO = #{orderNo}
  AND PROID = #{proId}

UPDATE TB_ORDER_ITEM
SET REVIEW_YN = #{yn}
WHERE ORDERNO = #{orderNo}
  AND PROID = #{proId}

mapper.select:
SELECT COUNT(*)
FROM TB_PRODUCT_REVIEW r
WHERE r.MEMID = #{memId}

SELECT COUNT(*)
FROM TB_INQUIRY i
WHERE i.WRITER = #{memId}

mapper.update:
UPDATE TB_MEMBER
SET ZIPCODE = #{zipCode},
    ADDRESSBASIC = #{addressBasic},
    ADDRESSDETAIL = #{addressDetail}
